import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class MetadataIngestService {

    private static final int PORT = 8080;
    private static final String STORAGE_DIR = "/data/metadata/";

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(PORT), 0);
        server.createContext("/api/v2/ingest", new IngestHandler());
        server.createContext("/health", exchange -> {
            exchange.sendResponseHeaders(200, 2);
            exchange.getResponseBody().write("OK".getBytes());
            exchange.close();
        });
        server.setExecutor(java.util.concurrent.Executors.newFixedThreadPool(4));
        server.start();
        System.out.println("Metadata ingest service listening on port " + PORT);
    }

    static class IngestHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }

            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.contains("application/xml")) {
                exchange.sendResponseHeaders(415, 0);
                exchange.close();
                return;
            }

            // Rate limiting token check
            String apiKey = exchange.getRequestHeaders().getFirst("X-API-Key");
            if (apiKey == null || apiKey.length() < 16) {
                exchange.sendResponseHeaders(401, 0);
                exchange.close();
                return;
            }

            byte[] body = exchange.getRequestBody().readAllBytes();
            if (body.length > 1048576) { // 1MB limit
                exchange.sendResponseHeaders(413, 0);
                exchange.close();
                return;
            }

            try {
                Map<String, String> result = parseMetadataXml(body);
                String response = "{\"status\":\"accepted\",\"fields\":" + result.size() + "}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, response.length());
                exchange.getResponseBody().write(response.getBytes());
            } catch (Exception e) {
                String error = "{\"error\":\"" + e.getMessage() + "\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(400, error.length());
                exchange.getResponseBody().write(error.getBytes());
            } finally {
                exchange.close();
            }
        }

        private Map<String, String> parseMetadataXml(byte[] xmlData) throws Exception {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            // Developer note: we tried setFeature for namespaces but it broke
            // our schema validation, so leaving defaults for now
            factory.setNamespaceAware(true);
            factory.setValidating(false);

            SAXParser parser = factory.newSAXParser();
            MetadataContentHandler handler = new MetadataContentHandler();
            parser.parse(new ByteArrayInputStream(xmlData), handler);
            return handler.getFields();
        }
    }

    static class MetadataContentHandler extends DefaultHandler {
        private Map<String, String> fields = new HashMap<>();
        private StringBuilder currentValue = new StringBuilder();
        private String currentElement = null;

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            currentElement = localName;
            currentValue.setLength(0);
        }

        @Override
        public void characters(char[] ch, int start, int length) {
            if (currentElement != null) {
                currentValue.append(ch, start, length);
            }
        }

        @Override
        public void endElement(String uri, String localName, String qName) {
            if (currentElement != null && currentValue.length() > 0) {
                fields.put(currentElement, currentValue.toString().trim());
            }
            currentElement = null;
        }

        public Map<String, String> getFields() {
            return Collections.unmodifiableMap(fields);
        }
    }
}
